int orangesRotting(vector<vector<int>>& g) {
    int R = g.size(), C = g[0].size(), fresh = 0, t = 0; deque<pair<int,int>> q;
    for (int r = 0; r < R; r++) for (int c = 0; c < C; c++) { if (g[r][c] == 2) q.push_back({r, c}); else if (g[r][c] == 1) fresh++; }
    int d[5] = {1, 0, -1, 0, 1};
    while (!q.empty() && fresh) { for (int k = q.size(); k > 0; k--) { auto [y, x] = q.front(); q.pop_front();
        for (int i = 0; i < 4; i++) { int yy = y + d[i], xx = x + d[i + 1]; if (yy >= 0 && yy < R && xx >= 0 && xx < C && g[yy][xx] == 1) { g[yy][xx] = 2; fresh--; q.push_back({yy, xx}); } } } t++; }
    return fresh ? -1 : t;
}
